package com.friendoncampus.credit.config;
import java.security.*;import java.security.interfaces.RSAPublicKey;import java.security.spec.X509EncodedKeySpec;import java.time.Instant;import java.util.*;import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.RSASSAVerifier;import com.nimbusds.jwt.*;import org.springframework.security.oauth2.jwt.*;import tools.jackson.databind.*;import tools.jackson.databind.json.JsonMapper;
public final class ServiceTokenDecoder {private final JsonNode trusted;private final String audience;public ServiceTokenDecoder(String a,String j){try{audience=a;trusted=JsonMapper.builder().build().readTree(j);if(!trusted.isObject())throw new IllegalArgumentException();}catch(Exception e){throw new IllegalArgumentException("Invalid service trust",e);}}public Jwt decode(String raw){try{SignedJWT t=SignedJWT.parse(raw);JsonNode e=trusted.get(t.getHeader().getKeyID());if(e==null||!JWSAlgorithm.RS256.equals(t.getHeader().getAlgorithm()))throw new IllegalArgumentException();RSAPublicKey k=(RSAPublicKey)KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(e.path("publicKey").asText())));if(!t.verify(new RSASSAVerifier(k)))throw new IllegalArgumentException();JWTClaimsSet c=t.getJWTClaimsSet();Instant n=Instant.now(),i=c.getIssueTime().toInstant(),x=c.getExpirationTime().toInstant();if(!"foc-service-auth".equals(c.getIssuer())||!"chat-service".equals(c.getSubject())||!c.getSubject().equals(e.path("subject").asText())||!c.getAudience().contains(audience)||!x.isAfter(n)||x.isAfter(i.plusSeconds(60))||c.getJWTID()==null)throw new IllegalArgumentException();return new Jwt(raw,i,x,t.getHeader().toJSONObject(),c.getClaims());}catch(Exception e){throw new BadJwtException("Invalid service assertion");}}}
